typedef struct { const char *id, *name, *version, *installed, *desc; const uint8_t *thumb; uint8_t cats, cat, has_image; } fwb_ent_t;
static const fwb_ent_t FWB[] = {
    { "amb", "AMB-1", "1.3.2", "1.3.2", "A generative ambient machine after Music for Airports: it plays itself from the start, breathing voices, bells on tape loops of unequal length, a gliding bass. You do not perform it, you tend it.", NULL, 17, 4, 1 },
    { "amenity", "Amenity", "2.1.1", NULL, "A live jungle tool built around classic breaks (Amen, Apache, Think) and your own. Hold white keys for rolls, builds, echo and Akai-style metallic stretch, play hits on the black keys, and shape the break with variation, warp, ringing feedback, lo-fi, EQ, saturation and compression.", NULL, 8, 3, 1 },
    { "arcticscream", "Arctic Scream p0larpatch", "2.1.1", "2.1.1", "Arctic Scream is a dark-ambient drone machine built on GR!MM: four tracks over FM, supersaw, formant, tonewheel, physical-model, phase-distortion and sample sources, plus Holvut, a feedback string-and-body loop that wakes, howls and overblows into screams. Drones wander and build like a storm; WARP and MORPH twist the sound, with a huge SPACE reverb and freeze, GRAIN, TAPE and a HORROR scale.", NULL, 1, 0, 1 },
    { "aurora", "AURORA", "0.8.0", NULL, "Epic film sounds: an eight-voice spectral pad of sine partials that drifts on its own, a swarm of saws, shaped wind, a shimmer plate, a tape delay and a freeze that holds a cloud of grains. Every page is a picture the four knobs shift, and HOME is an aurora bent by the sound.", NULL, 1, 0, 1 },
    { "berlinan", "Berlinan", "0.5.1", "0.5.1", "A generative Berlin School MIDI sequencer: a small ensemble of voices that repeat, phase against each other on loops of unequal length and earn their mutations over time. The FM-1 makes no sound with it: each voice goes out over USB on its own MIDI channel to your synths, as Berlinan for macOS...", NULL, 16, 4, 1 },
    { "bytemania", "Bytemania", "1.3.2", NULL, "A bytebeat synth: play one-line formulas, tweak them with the knobs, and write your own, with a random button in the formula creator that is really fun. A beta, built on Dinghy.", NULL, 1, 0, 1 },
    { "caravel", "Caravel", "0.13.0", "0.13.0", "Six-engine FM-1 synthesizer: ANALOG, PHYS, SEM, HADES, DRONE and ENSEMBLE; BUILD/PLAY, live panel/MIDI note CAPTURE, CHORD EXT, STASIS and evolving performance.", NULL, 1, 0, 1 },
    { "carnacos", "Carnac OS", "0.9.6", NULL, "CARNAC OS is a dual-timbral wavetable synth inspired by neolithic monuments and forgotten rituals. Built for deep sound design and immediate control, with a MAQ 16/3-style sequencer and a J6-style chord arp. The PCM waves need a separate installer: get it from my GitHub page.", NULL, 1, 0, 1 },
    { "chipbox", "Chipbox", "1.5.5", "1.5.5", "A ultra-refined Chiptune music editor, featuring over 35 classic chips such as NES, Gameboy, heck even the Sunsoft 5B! Pages with their own meter, tempo and glide, so waltzes and 7/8 grooves are easy. Gimmick fans rejoice!", NULL, 2, 1, 1 },
    { "choralroot", "ChoralRoot", "0.41", "0.41", "A Telepathic Orchid-style chord instrument: one hand plays roots, the other shapes chords; voicings, performance modes, bass and a looper.", TH_choralroot, 4, 2, 1 },
    { "clipper", "Clipper", "1.3.1", "1.3.1", "A deep synth grown out of SLOOP: 23 engines and 407 sounds, from HYBRID (three oscillators, two filters, a mod matrix) to six-operator FM, wavetables, wave sequencing, a Juno and physical models; arp, step sequencer, MPE and a web editor for every parameter.", NULL, 3, 1, 1 },
    { "conductor", "CONDUCTOR", "1.0", NULL, "A pocket symphony orchestra groovebox with strings, woodwinds, brass and percussion. Compose in piano roll or musical notation, conduct individual sections with articulations, dynamics and expression curves, and arrange patterns into complete pieces.", NULL, 2, 1, 1 },
    { "coralflower", "CoralFlower", "0.7.1", "0.7.1", "Chords after the Orchid, with controls made for the FM-1: one key plays a chord with a bass note. Also 27 scales, an arpeggiator, a sequencer with drums and a song mode, and a pixel flower that grows as you play.", NULL, 4, 2, 1 },
    { "ctl", "CTL-1", "1.0.3", NULL, "A MIDI controller: notes in any scale with its chords on the black keys, four banks of knobs, an arpeggiator and Euclidean drums, with General MIDI sounds of its own when nothing is connected.", TH_ctl, 16, 4, 1 },
    { "cultbox", "CULTBOX", "1.2", "1.2", "A three-channel groovebox: a Polivoks-style duophonic synth (PLVKS), an Elka-style sample drum machine with a step sequencer, and a dub siren, with BBD echoes, per-channel character effects, arp, scales and a mixer with panning.", NULL, 2, 1, 0 },
    { "csfm1", "cursed os", "0.18.5", NULL, "An Elektron-style six-track groovebox for the FM-1, with Elektron Syntakt support. One-press quick-start loops, generators for acid lines, dub chords, held atmospheres and modular bleeps, trig conditions and locks, a DJ filter and FX pad, and the keys set the song's key. Built on JIANT FM.", NULL, 2, 1, 1 },
    { "drift", "DRIFT", "0.9.6", "0.9.6", "An ambient instrument for live sessions: warm synths, spacious pads and delicate plucks over a generative Euclidean sequencer on one track, with delays and reverbs from spring to shimmer. Built on Felucca.", NULL, 1, 0, 1 },
    { "drumlab", "Drumlab", "0.1.3-beta", "0.1.3-beta", "Microtonic, for the FM-1! Roll the dice for a kit, build one from scratch, or bring in your Microtonic presets and patterns. Share kits and patterns as files, and send it all to your Teenage Engineering PO-32! Built on Chipbox!", NULL, 8, 3, 1 },
    { "dub", "DUB-1", "1.4.3", "1.4.3", "A generative dub techno machine that plays itself from the moment it is on: chord stabs into a tape echo, FM pings, a sub bass on five grooves, a ducking kick, crackle, and an eight-bar arrangement with breaks and fills.", NULL, 2, 1, 0 },
    { "dubwise", "DUBWISE", "0.4.2", NULL, "In dub, the mixing desk is the instrument. Dubwise FM is an eight-channel reggae band (FM drums, bass, skank, organ, melodica or horns, sirens and shouts), each channel with a mute and a throw, feeding a tape echo you can push into feedback and a spring reverb you can kick. Quantised mutes land on the one with a countdown, the stepped Big Knob filter clicks like King Tubby's, and every drop, throw and sweep is yours: nothing plays itself. Record your moves into a song, recall them as scenes, or take the eight stems out over USB.", NULL, 2, 1, 1 },
    { "duell", "DUELL", "1.3.1", "1.3.1", "A MULTIMORPHING bitimbral synth: two complete parts, three ways to play them together, and a morph that glides between two versions of every sound. Ten engines with wavetables, twin filters, effects and a mod matrix. Macros and MIDI presets for Circuit Tracks and MPC/Force. Velocity, aftertouch.", NULL, 1, 0, 1 },
    { "dungeontracker", "Dungeon Tracker", "1.5", NULL, "Four Track Groovebox with a dungeon crawler cooked into the home screen for the visualizer. Create your party from 8 heroes, store up to 6 sequences then string them together in Song mode!", NULL, 16, 4, 1 },
    { "dx747", "DX747", "0.1", "0.1", "An eight-part multitimbral DX7 module. Every part has its own MIDI channel and up to eight layered DX7 voices, with key splits, velocity windows and 64 scenes. A master filter, shared reverb and delay, DX7 ROM import and a web configurator. Played and controlled over MIDI.", NULL, 1, 0, 1 },
    { "echofield", "ECHOFIELD", "0.2.13", NULL, "A granular sampler: a few seconds of any sound become slow clouds, sparkles, tape loops and swells, played from the keys and knobs. 14 factory sounds, your own samples (or recorded over USB), filter, delay, reverb and tape, and a companion web app for samples, presets and recording.", NULL, 1, 0, 1 },
    { "elasticat", "Elasticat", "0.6.93", "0.6.93", "A norns-style loop mangler: six tracks of loops, slices and grains with a 128-step sequencer, parameter locks, hold menus and a 128-slot sample pool. Loads WAVs from your RemoteFM1 folder (audio/), saves projects and takes to data/. A Fantasy CFW: runs in RemoteFM1 only, never on an FM-1.", TH_elasticat, 16, 4, 1 },
    { "etch", "ETCH", "1.88", NULL, "Draw your own waveforms, morph between sounds, and bring them to life with modulation, evolving textures, and powerful effects. From warm analog-inspired tones to wild experimental soundscapes, ETCH puts sound design right at your fingertips.", NULL, 1, 0, 1 },
    { "evilgenius", "EVIL GENIUS", "0.1.3", "0.1.3", "A SID chip groovebox that talks. Six tracks of C64 SID voices and SAM speech, per-step sound locks, conditions, ratchets and MIDI FX, and a tower of eight retro effects with a send per track. Bluetooth MIDI and USB audio. A C64 game for a screen.", NULL, 2, 1, 1 },
    { "fartmachine", "Fart Machine One", "1.1.0", NULL, "A questionable musical instrument: ten artisanal farts, reverb, delay and a sixteen-step sequencer.", NULL, 16, 4, 1 },
    { "felucca", "Felucca", "1.8.2", "1.8.2", "The custom firmware the others build on: the FM-1's own synth engines, a sequencer, effects and a better panel, with an editor in the browser.", TH_felucca, 19, 0, 1 },
    { "fimba", "FiMba-1", "0.7.0", NULL, "A physically modelled kalimba: tines laid out like the real one, thumb-roll chords, mbira patterns, a sound hole to cover, grains, tape and a plate reverb. Play it in the browser first.", NULL, 1, 0, 1 },
    { "fizz", "FIZZ", "0.12.0-beta.19", "0.12.0-beta.19", "A step sequencer for FM TONE, ChoralRoot's FM voice: eight tracks sharing 16 voices, p-locks, a pool of 128 sounds, pages with their own start and end, conditions, chance, ratchets and chords of up to six notes. Built by this site from FIZZ's release to WebAssembly (.rfm1) and run natively here; PLAY starts the demo pattern, REC turns the keys into a keyboard.", NULL, 2, 1, 0 },
    { "chimeravocal", "FM-1 Chimera Vocal", "0.8.0", NULL, "A singing human voice for the FM-1, ported from Jameson Hodge's CHIMERA. A simulated airway (lungs, vocal folds, throat, mouth, nose) sings words a syllable per key, or holds vowels you shape with the knobs. Write the words in the browser Studio and send them over USB.", NULL, 1, 0, 1 },
    { "sid", "FM-1 SID", "0.3", "0.3", "C64 music on the FM-1: a 6510 runs each tune's own code and reSID plays it, PSID and RSID. A GoatTracker 2 editor on the FM-1 itself with ten GT2 example songs, a SID synth with a sequencer and effects, and any .sid sent from the browser plays at once.", NULL, 2, 1, 1 },
    { "fmkick", "FM-KICK", "0.5.1", NULL, "A kick drum synthesizer with a sequencer of up to 32 steps: seven kinds of kick and 48 parameters, p-locks of any parameter on any step, step conditions and chance, nine generators, four LFOs, live and final effects with a hall reverb, three pattern banks, four projects and six themes.", NULL, 8, 3, 1 },
    { "trax", "FM1-TRAX", "0.9.5", "0.9.5", "A Mega Drive / Genesis music tracker. It emulates the YM2612 and SN76489 chips: six FM channels, three square waves and noise, with Deflemask-style effects, 128 FM presets, a drum kit on the DAC, 256 song slots, a demo song and VGM export.", NULL, 2, 1, 1 },
    { "fmav1", "FMav-1", "0.5.1", NULL, "A semi-modular mono synth: VCO, self-oscillating 4-pole ladder filter, LFO, ADSR, VCA, wave folder, S+H, mixer and a patchbay with normals and dummy plugs. Four tracks on their own MIDI channels, MIDI clock sync, arpeggiator, chorus, delay and reverb, 90 sounds.", NULL, 1, 0, 1 },
    { "fmel1", "FMEL-1", "1.3", "1.3", "FMEL-1 turns the FM-1 into a Mellotron: every key plays its own length of real tape, recorded from Taijiguy's 1973 M400S: flute, choir, cello and vibes, plus a lo-fi piano. Layer a second sound and colour it with tape wow, flutter, hiss and wear, vibrato, echo, hall or plate reverb, a speaker EQ and a half-speed motor switch. ARP and a 16-step sequencer play along, and Javi's animated players act out each sound.", NULL, 16, 4, 1 },
    { "fmini", "FMini-1", "2.6.0", NULL, "A three-oscillator monosynth in the spirit of the classic Moogs: a 24 dB/octave ladder filter, two contours, 100 factory patches, an arpeggiator, a sequencer and MIDI. Built on Felucca.", NULL, 1, 0, 1 },
    { "fmlarynx", "FMLarynx", "0.4.2", "0.4.2", "A throaty talking formant synth with a 303-style sequencer: a saw wave through a three-formant vowel filter, resonant low-pass, drive and ping-pong delay. 16 steps with vowels, accent and slide, a pattern randomizer, 16 stored patterns, Bluetooth MIDI and tight clock sync.", NULL, 1, 0, 0 },
    { "fomni", "FoMni", "0.4.1", "0.4.1", "A chord harp inspired by the Omnichord: strum the white keys, pick chords on the black ones.", NULL, 4, 2, 1 },
    { "frasil", "FRASIL", "3.3.1", "3.3.1", "An ambient drone instrument: tap a key to latch a drone, a note or a chord in your key. Three layers a voice into a big reverb with shimmer and freeze; GLINT's icy FM bells on top, by hand, arpeggio or sequence; BASS a deep line below, held or sequenced; three LFOs keep it all moving.", NULL, 1, 0, 1 },
    { "ghoulbox", "GHOULBOX", "2.4", NULL, "Dungeon synth: a cathedral hall reverb, tape and crush, a hurdy-gurdy engine, choirs, organs and recorded psaltery and harp, an old-RPG screen with wall torches.", NULL, 3, 0, 1 },
    { "glitch", "glitch", "2.0.2", "2.0.2", "Neon-noir groovebox firmware for the M-VAVE FM-1: four tracks, seven sources, tape and megacity space FX, sixteen scales (Insen, Hirajoshi, Iwato, whole tone), and forty-four Blade Runner factory sounds. Its screen: a glitched landscape that tears with the sound.", NULL, 2, 1, 1 },
    { "golana", "Golana", "1.3", NULL, "One analog-style synth laid out like the classic microKORG, with a screen that draws the sound.", NULL, 1, 0, 1 },
    { "golf", "Golf", "1.0", "1.0", "A wavetable synthesizer: two oscillators that morph through 130 wavetables, with unison and warps, a ladder filter, a modulation matrix and effects. Its 32-step sequencer can move the wavetable and the filter on every step.", TH_golf, 1, 0, 1 },
    { "grimm", "GR!MM", "2.0.2", NULL, "Dark ambient, dungeon synth and deathdream firmware: 4 tracks, 7 sound sources, real recorded choirs, tracks that play by themselves, and long tape, granular and reverb effects.", NULL, 3, 0, 1 },
    { "guitchordi", "GuitChordi", "0.1.0-beta.1", "0.1.0-beta.1", "A chord and string instrument: 16 synthesized sounds, 50 chord styles, editable voicings, guitar tunings, and Freeplay, Strum and Arp modes with partial-chord pulses.", NULL, 4, 2, 1 },
    { "hadal1", "HADAL-1", "1.0.1", NULL, "Generative dark ambient: drones, demonic and angelic choirs, bells and 135 sound effects that keep changing by themselves across 15 worlds, with 40 melting pictures. Play bells or latch choir voices on the keys, or play and hold effects. Works on older and newer FM-1s (both flash chips).", NULL, 16, 4, 1 },
    { "hawkchua", "hawk-chua", "2.1.7", "2.1.7", "Noise and modeling synth with GM-style presets (4 banks, 512) and a 4-track tape recorder: each voice a live Chua circuit or noise program, through vactrol gates into resonators and piano, drum, voice, flute, brass, bowed, reed and bird waveguides, with temple, cathedral and mosque reverbs. GM...", NULL, 1, 0, 1 },
    { "hortator", "Hortator", "1.0.1", "1.0.0", "A drum machine: eight tracks of drums, a step sequencer, Grids, a pumping compressor, LFOs, resonators and live effects. Play it in the browser first.", NULL, 8, 3, 1 },
    { "hyp1", "HYP-1", "1.5.54", "1.5.54", "Hypnotic techno and acid: a breathing pad, a deep drone, a generative 303 line and grain over drums you sequence. Flip patterns on the bar, break it down, build it up. Forked from AMB-1. One of a pack of four: LOF-1 (a lofi groovebox), ECO-1 (a plant plays it) and GRAV-1 (a star and its planets), experimental, on its project page.", NULL, 2, 1, 1 },
    { "jiant", "JIANT FM", "10.26", NULL, "A bio-synthetic groovebox: six tracks drawn as living beings in thermal colours, eight engines (FM6 with Dexed, analog, phase, voice...), mutating macros, song mode from SLOOP. Not yet tested much on a real FM-1.", NULL, 2, 1, 1 },
    { "kwasub", "K-WASUB", "1.1.03", "1.1.03", "Runs on the latest FM-1 chip. A bass synth for DnB, dubstep, dub and techno: deep subs, reese, growls and 808s. Two of nine engines play together, the keys change the wobble live, and one button plus a knob puts an LFO on any setting. With drums, a bass sequencer and live FX pads.", NULL, 1, 0, 1 },
    { "karma", "KARMA", "3.1.4", "0.0.0", "A four-track groovebox: an acid bass or a Juno-style poly, physical modelling, two dozen synthesis models and a drum synth. A 64-step sequencer with song mode, generators that write parts on one chord plan, pixel characters, and USB audio with six stems, MIDI out and DAW sync.", TH_karma, 2, 1, 1 },
    { "krisjangle", "Kris Jangle", "0.14", "0.14", "Kris Jangle is a Christmas game for the FM-1: it plays the start of a carol and you replay it on the keys, building three notes per level up to the whole song. Four carols, three play modes from guided EASY to sound-only HARD, and Grump Mode on three misses.", NULL, 16, 4, 0 },
    { "loafbreaker", "LOAF BREAKER", "0.9.68", NULL, "A hardcore kick synthesizer powerhouse (gabber, terror, speedcore) and a breakbeat chopper (Based on CHOPPAH) : twenty kicks with distortion, sliced breaks, effects, drums, songs with drops, a BEGINNER mode, a DAW-like Studio on PC. The editor adds up to 8 breaks: yours or from a library of 90+.", NULL, 8, 3, 1 },
    { "loom", "LOOM-8", "0.16.2", "0.16.2", "A groovebox inspired by the OP-XY: eight tracks on nine engines, step tricks and locks, weave, a conductor and throws.", NULL, 2, 1, 0 },
    { "mpyre", "M-PYRE", "1.0.3", NULL, "A riffbox for rock and metal: real guitar, bass and drum samples, an amp engine with cabinet IRs, pedals and guitar effects, plus all of SLOOP's synth engines. Bend strings, play whammy, wah and palm mutes live, record on the 4-track and turn riffs into songs.", NULL, 2, 1, 1 },
    { "mvsynth2", "M-Vsynth2", "1.3", "1.3", "Synth2, the open-source recreation of Synth1, on eight voices across both cores: two oscillators and a sub, five filters (LPDL among them), two LFOs, distortions and phasers, EQ, delay, chorus and Synth1's arpeggiator. It plays Synth1's .sy1 patches, with the Synth2 Factory bank built in and 1024...", NULL, 1, 0, 1 },
    { "matryoshka", "Matryoshka", "1.18.1", NULL, "A modular synth for the FM-1: 30 factory patches built from nested modules, from classic polysynths to drum machines, each played with four knobs per page, plus a step sequencer with patterns and songs. Build your own patches in the browser editor and send them to the FM-1 over USB.", NULL, 1, 0, 1 },
    { "melodee", "Melodee", "1.6.1", "1.6.0", "Total playing pleasure, far beyond Felucca: recording without quantize, microtonal scales, a Casio CZ-1, a bit-by-bit Dexed, scale modes made for an MPC Sample as its companion.", TH_melodee, 3, 0, 1 },
    { "mightyarp", "Mighty Arp", "1.5", NULL, "Mighty Arp, from the creator of Mighty Synth Sampler, is a 4-op FM/subtractive synth built around a chance arpeggiator. Just hold a chord and let chance play the melody. 50 sounds plus a RANDOM mode that invents new ones, a 32-step sequencer, chords, effects and more.", NULL, 1, 0, 1 },
    { "minitone", "Mini-Tone", "1.0.5", "1.0.5", "Felucca with six tracks and new engines: SID, Braids' 48 models, a TB-303 and engines after Elektron's Analog Four, SY Chip and Digitone 2, a ping-pong delay and a new reverb. Built on Felucca 1.5.", NULL, 3, 0, 1 },
    { "mnm1", "MNM-1", "1.0.1", NULL, "Six monophonic tracks of synth and FX machines, pages of eight knobs, a filter and a tape delay on every track, three LFOs a track, parameter locks and slides. Forked from Hortator, with sounds ported from MONO2K.", NULL, 2, 1, 1 },
    { "modelar", "MODELAR", "0.3", "0.3", "A semi-modular drone synth played like a Kaoss Pad: four oscillators modulating each other through eight routings, and keys that move a cursor on an XY pad instead of playing notes: white keys are points, black keys gestures. ARP, a polymetric sequencer, a clock in Hz and eight generative environments.", NULL, 1, 0, 1 },
    { "mono2k", "MONO2K", "1.11", NULL, "Six mono machines in the spirit of Elektron's Monomachine: FM, superwaves, wavetables, a SID, a voice and four drum synths, one per track. A 64-step sequencer with parameter locks, trig conditions and ratchets, a lofi bus, four demo parts and a web patch editor.", NULL, 2, 1, 1 },
    { "mope1", "MOPE-1", "0.4.1", "0.4.1", "A sad wavetable synth played by a pixel blob in a rainy room: its eyes are the filter, its mouth the envelope, its tears the delay. Gloomy beats with auto-bass, an arpeggiator, a pattern sequencer, twelve punch effects on the black keys, and presets of your own.", NULL, 1, 0, 1 },
    { "morse", "MORSE", "0.6", NULL, "Learn and use Morse code: key on the piano keys (straight key or iambic paddles) and read what you sent, drill short and long presses, learn by sound with flash cards, hear endless practice, type letters and CW phrases. Keying goes out over USB or Bluetooth MIDI in the Vail format.", NULL, 16, 4, 1 },
    { "mutabledreams", "Mutable Dreams", "2.3", "2.3", "Mutable Dreams by Kid Bunka / Christoph Link, built to WebAssembly (.rfm1) and run natively here.", NULL, 1, 0, 1 },
    { "nachtfahrt", "NACHTFAHRT", "1.0.2", NULL, "Generative 1970s Berlin School: two sequencers drift against each other over a drone, in eight endless pieces. Play a melody on the white keys and the lead answers it, takes it as its theme and grows new ideas from it.", NULL, 1, 0, 0 },
    { "niagaradrift", "Niagara Drift", "0.3", "0.3", "Two drones that breathe and drift on their own, after the Lyra-8, Subharmonicon and DS-2: twelve presets on the white keys, gestures and scenes to move them, an LFO, delay and a reverb that freezes. Press PLAY to fade them in.", NULL, 1, 0, 1 },
    { "nomansky", "No Man Sky FM", "0.9", NULL, "No Man Sky FM is a space adventure you play while you make music, built on SLOOP 2.7.1: one hand flies the ship with two knobs while the other plays the soundtrack. Land on planets, mine, fight sentinels and pirates, race, escort ships and warp between stars, while every SLOOP screen (four-track sequencer, engines, arp, FX) floats over the game.", NULL, 16, 4, 1 },
    { "obervave", "OberVave", "3.5.2", "3.5.2", "An 8-voice analog-style poly in the spirit of the classic American polys of 1979-84, now on four tracks: each its own sound, arp and sequence; a mixer with chorus, delay, plate reverb and drive sends, a master with DJ filter and compressor. Tracks start on the bar, patterns keep their sounds.", NULL, 1, 0, 1 },
    { "obssynth", "ObsSynth", "0.2.0", NULL, "A four-voice synthesizer: two oscillators per voice, each STD (8 waves), SUPER (7 detuned saws, squares, triangles or sines), WT or GRAIN; a 12/24 dB multimode filter, two ADSRs, two LFOs, unison, delay, reverb and chorus. 16 factory presets, 16 of yours. Play it in the browser first.", NULL, 1, 0, 1 },
    { "orbit", "ORBIT", "1.0.0", "1.0.0", "A four-track groovebox: three synths and a drum machine in a colour-coded Synth, Drum, Event Tape and Mixer workflow, loops turned into songs, user macros, screens after the OP-1. Based on SLOOP.", NULL, 2, 1, 0 },
    { "orgigs", "OrGigs", "1.0.2", NULL, "It's an organ. Three manuals with 84 free-running tone generators and no voice stealing, eight models from tonewheel and combo organs to pipe organs and free reeds, drawbars, percussion, rotary, drive, delay and reverb, 16 performance setups, three MIDI zones and Yamaha SEQTRAK control.", NULL, 16, 4, 1 },
    { "patchwerk", "Patchwerk", "1.0.3", "1.0.3", "A modular synth for the FM-1. With over 80 modules, including synth engines, samplers, filters, effects, sequencers, and generative tools, you can build, patch, and perform directly on the hardware.", NULL, 1, 0, 1 },
    { "penumbra", "Penumbra", "1.6", NULL, "An ambient space-drone synth that plays itself until you do. Drone voices drift in and out, a far-off voice sings, and the sound glides from scene to scene as an eclipse crosses the screen. Every key is in tune, and loops follow each key change. A thick, slow drone, like the Solar 42.", NULL, 1, 0, 1 },
    { "perf1", "PERF-1", "0.17.0", "0.17.0", "A groovebox that plays itself while you steer it: nineteen genres, FM pad, bass, acid and pluck voices, drums with a step sequencer, an auto-DJ, effects you play on the keys, scenes, and a Jam page to play along. Store your pieces, and share them through the online library.", NULL, 2, 1, 1 },
    { "pigeon", "PIGEON", "0.4.1", NULL, "An old-school hip-hop and house sampler after the SP-404 and the PO-33: two song samples and a 16-pad kit, up to 32 chops a song, a 64-step sequencer, patterns and a song arrangement. Built on Felucca.", NULL, 10, 1, 1 },
    { "pond", "POND", "0.1.2", "0.1.2", "POND by superxor, built to WebAssembly (.rfm1) and run natively here.", NULL, 16, 4, 0 },
    { "purplemonkey", "PurpleMonkey", "0.12", NULL, "A first instrument for toddlers: random key bashing and knob turning are rewarded with dancing animated pets and little musical sequences. Press a key, any key.", NULL, 16, 4, 1 },
    { "quantumgammawave", "Quantum GammaWave", "4.1.0", "4.1.0", "A six-track groovebox for the M-VAVE FM-1: nine engines and 273 sounds (analog, six-operator FM, wavetable, digital drums), a 64-step sequencer with probability and ratchets, song mode, scales and chords, a mod matrix and three FX buses, plus a browser emulator and a web editor.", NULL, 2, 1, 1 },
    { "quartz", "QUARTZ", "0.6", NULL, "A four-track groovebox: Plaits' 24 models, a 16-pad kit, a step sequencer with p-locks and trig conditions, eight generative sources (Game of Life, chord progressions, Tonnetz walks, orbits, an improviser that learns from you...), punch-in effects and an animated scene on every page.", NULL, 2, 1, 1 },
    { "rainbow", "Rainbow Mode", "1.1.5-rb", "1.1.5-rb", "A music toy for little children: 63 cartoon friends, every key in tune, chords, strumming, songs to follow and an ear game, notes on a staff, a volume cap for small ears.", NULL, 16, 4, 1 },
    { "ravel", "Ravel", "1.41.2", NULL, "An eight-track groovebox for sound design: thirteen synth engines, struck percussion and 33 drum machines after the Machinedrum, on an influence grid where any track can trigger, excite or modulate any other.", NULL, 2, 1, 1 },
    { "remotefm1", "RemoteFM1", "0.3.6", "0.3.6", "The firmware this site installs, running as itself. On its own (0.3) the FM-1 is a DX7 with Yamaha's ROM voices, a MIDI controller, a looper and an arp; when a computer connects it becomes that computer's panel.", NULL, 16, 4, 1 },
    { "rhythmer", "Rhythmer", "0.1.0-beta.2", NULL, "A hands-on groovebox firmware for the FM-1. Shape sounds, build patterns, and find your own groove. Up to six assignable tracks, sound design, sequencing and performance. Free and open source, built on JIANT and reworked by Jazzy Rhythmer.", NULL, 2, 1, 1 },
    { "ripple", "Ripple", "0.6.1", "0.6.1", "Instruments written in Lua (droplets) playing sounds written in Faust or C (currents), inspired by norns. Built-in droplets to start; add your own as Lua scripts in your RemoteFM1 folder (code/ripple/droplets) and pick \"reload folder\". A Fantasy CFW: runs in RemoteFM1 only, never on an FM-1.", NULL, 16, 4, 1 },
    { "ruido", "Ruido", "0.7.1", NULL, "Ruido is a 4-oscillator drone and noise synthesizer firmware for the M-VAVE FM-1 with coupled voices, dual resonant filters, scene morphing, and pressure-sensitive performance effects. It is created as a dry stereo sound source for external pedals and modular setups.", NULL, 1, 0, 1 },
    { "rupture", "RUPTURE", "1.93", "1.93", "A monophonic bass synth on Cycle Exchange Synthesis: two sub-oscillators, a ladder filter, Channel EQ, eight effects from MOSFET drive to octave fuzz, a step sequencer up to 128 steps and an arpeggiator.", NULL, 1, 0, 1 },
    { "s1vave", "S1Vave", "2.0.1", NULL, "An 8-voice virtual analog tweak synth: authentic 4-pole resonant filter, dual sub-oscillator, ADSR envelopes, 64-step sequencer, and hands-on live performance controls.", NULL, 1, 0, 1 },
    { "samsara", "SAMSARA", "1.0.0", "1.0.0", "A slow generative ambient piece that plays itself for hours and never repeats: a choir pad, soft bells, a gliding bass and a rare low ground drift through harmonies and colours like weather. Four pieces, four knobs to tend it (Mood, Density, Drift, Space). A fork of AMB-1.", NULL, 1, 0, 0 },
    { "sid1", "SID-1", "1.0.1", NULL, "The Commodore 64's SID chip, twice for six voices. Its web app edits patches and takes them straight from .sid game music files.", NULL, 1, 0, 1 },
    { "sidj", "SiDJ", "1.5.1", "1.5.1", "Plays C64 SID music from HVSC on an emulated 6581 or 8580 and lets you remix every voice live: transpose, mute, solo, swap waveforms, bend envelopes and filter, add LFOs, ride the tempo. Out of the jack, as USB audio or over ASID to a real SID. MIDI clock from the tune, or the tune synced to yours.", NULL, 16, 4, 1 },
    { "sidou", "SIDOU", "1.20.0", NULL, "Turns the FM-1 into a C64 SID machine: two SIDs measured on real chips, a GoatTracker 2 tracker and sequencer with swing, Euclid, ratchets and punch pads, .sid playback, .sid to song and sounds, LAB, MIDI parts and chords for a DAW, AI-made songs and sounds, Bluetooth MIDI and keyboards, Live Link.", NULL, 16, 4, 1 },
    { "skiff", "Skiff", "2.7", "2.7", "Six tracks of synths and drums with a groovebox's workflow: fourteen engines, a 64-step sequencer with chords, ratchets, trig conditions and locks, songs, PERFORM with scenes, six themes and a browser editor; FM6 sounds built from scratch on the unit. Built on Felucca, with most of Felucca 1.6.1's work brought over (the second core, MIDI LEARN, INSERT); Felucca's sounds and projects load. Also runs on the SMK-37 Pro. Coming from 1.x: 2.0 saves in new formats - update on Skiff's own page (it backs up and converts), or back up in its editor first.", NULL, 2, 1, 1 },
    { "sloop", "SLOOP", "2.8.5", "2.8.4", "A live groovebox: tracks, layers, a step sequencer, song mode, punch-in effects and samples, played on the FM-1 in real time.", TH_sloop, 2, 1, 1 },
    { "smileyface", "Smileyface", "1.1.5", "1.1.5", "You're making acid, baby! Smash that LFO button until you hear something you like, and then twist those knobs! Now with 100% more FX! A truly trippy experience! Built on Chipbox.", NULL, 1, 0, 1 },
    { "speak37", "Speak37", "1.0", NULL, "The talking synth, its FM-1 build: every key speaks the next word of a sentence at its pitch and chords speak in harmony; nine voices, 20 banks of sentences and songs, RHYTHM with an 808.", NULL, 16, 4, 1 },
    { "spellbox", "SPELLBOX", "0.3", "0.3", "SPELLBOX turns the FM-1 into a talking spelling toy after the 1978 Speak & Spell: an 8-character fluorescent display, a 10-pole LPC voice at 8 kHz through an 8-bit DAC, and the SPELL, LETTER, SAY IT, SECRET CODE and MYSTERY WORD games over four levels, with the keys as an A-to-Z keyboard. SPEAK...", NULL, 1, 0, 1 },
    { "stallion", "Stallion", "1.1", NULL, "A synthesizer with 26 engines and 819 level-matched factory sounds: three-oscillator HYBRID, six-operator FM, wavetables, early-1980s polysynths, a semi-modular two-filter voice, physical models and more. One instrument with a modulation matrix, arpeggiator and step sequencer, edited in the browser.", NULL, 1, 0, 1 },
    { "sy1", "SY1", "0.4.0", "0.4.0", "A Synth1-inspired polysynth that plays two sounds at once in bitimbral mode: layered, split or on two MIDI channels. 256 presets by category, 1,024 user slots. Two oscillators plus sub, FM, ring mod, sync, four filters, arp, drone and effects. 3,174 more sounds in the Patch Manager.", NULL, 1, 0, 0 },
    { "tekstuur", "Tekstuur", "2.0", "2.0", "An instrument for slow, evolving sound. Four layers play recorded sources as drifting loops, grains, time-stretch or resonating strings, mixed by a vector point that moves by itself, with shimmer reverb and freeze.", NULL, 1, 0, 1 },
    { "tessera", "Tessera", "3.6.1", "3.6.1", "Composing through systems on the FM-1. Thirteen generators, your own steps, or a phrase you play on the keys make parts that follow, answer and share one harmony. Sections, entries and a shape for the whole piece let a project unfold over minutes or hours. Play it by hand, or let it play.", NULL, 2, 1, 1 },
    { "tonitor", "Tonitor", "0.55", NULL, "Six tracks for live ambient and experimental music: three synth engines, patches generated by algorithm, free-length loops with up to ten overdubs each, a granulator, filters and a lush reverb.", NULL, 17, 4, 1 },
    { "trapstationos", "TRAPSTATION OS", "1.1.0.2", "1.1.0.2", "A trap and phonk groovebox: six tracks with 808s, FM keys, bells and pads, generators for drums, hats, chords and bass, a sampler with slices, a piano roll, a live performance page with mutes, effect throws and bar jumps, and tape, VHS and vinyl colour on the master.", NULL, 2, 1, 1 },
    { "vector37", "Vector37", "0.3.2", NULL, "An orbiting overtone synth: four corners of two overtone generators each, a sun on a path and a moon around it decide how much of each you hear; the knobs shape the selected planet. Made for the SMK-37, here its FM-1 build. After the Beetlecrab Vector.", NULL, 1, 0, 1 },
    { "vesper", "VESPER", "2.0.2", "2.0.2", "An ambient worship synth. Each scene layers four lush voices in any major key around a crystal orbit home screen: pads, plucks, piano and swells. Shape them with drive, tone, granular clouds, shimmer, reverb and delay, then play live over the scene or record into it.", NULL, 1, 0, 1 },
    { "viscera", "Viscera", "2.6.0", NULL, "Viscera by De-Pattern, built to WebAssembly (.rfm1) and run natively here.", NULL, 16, 4, 0 },
    { "x0x", "X0X", "1.2.2", "1.2.2", "A groovebox: 909 and 808 drums, two 303s with TB-3PO, a breakbeat generator and song mode.", NULL, 10, 3, 1 },
    { "yehnah", "Yehnah", "0.1.0", NULL, "Six-track groovebox firmware with 25 synthesis engines, 800+ presets and no samples. Chord layouts you play with one thumb, a 64-step sequencer, idea generators, songs with arrangement, SWARM, TRACE and XYZ sound-morphing pads, a browser editor and emulator.", NULL, 2, 1, 1 },
    { "zen1", "ZEN-1", "1.2", "1.2", "Ambient as a living window: cherry petals on a river, koi in a pond, fireflies under a real moon, and every movement a note. Set it down and let it play; the keys play along, the knobs shape the scene.", NULL, 1, 0, 1 },
};
static const char *const FWB_FAV0[] = { "choralroot", "sloop", "elasticat", "felucca", "melodee", "golf", "x0x", "hortator", "amb", "tekstuur", "ripple", "hyp1", "drumlab", "fizz", "coralflower", "fomni", "guitchordi" };
